class Node:
    def __init__(self, value, next=None):
        self.value, self.next = value, next

head = Node(1, Node(2, Node(4)))
second = head.next
second.next = Node(3, second.next)   # insert 3 after 2: two pointer changes

node = head
while node:
    print(node.value, end=" ")       # 1 2 3 4
    node = node.next

_cache = {}

def lookup(key):
    if key not in _cache:
        _cache[key] = "x" * 1000     # never evicted: a leak by design
    return _cache[key]

for i in range(1000):
    lookup(i)
print(len(_cache))                   # 1000 entries and counting
