def rpn(tokens):
    ops = {"+": lambda a, b: a + b, "-": lambda a, b: a - b,
           "*": lambda a, b: a * b, "/": lambda a, b: a / b}
    stack = []
    for t in tokens.split():
        if t in ops:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[t](a, b))
        else:
            stack.append(float(t))
    return stack.pop()

print(rpn("3 4 + 5 *"))   # 35.0

from collections import deque

def window_max(nums, k):
    out, q = [], deque()          # q holds indexes, values decreasing
    for i, x in enumerate(nums):
        while q and nums[q[-1]] <= x:
            q.pop()
        q.append(i)
        if q[0] <= i - k:
            q.popleft()
        if i >= k - 1:
            out.append(nums[q[0]])
    return out

print(window_max([1, 3, -1, -3, 5, 3, 6, 7], 3))   # [3, 3, 5, 5, 6, 7]

class Ring:
    def __init__(self, size):
        self.buf, self.size, self.head, self.count = [None] * size, size, 0, 0

    def push(self, x):
        self.buf[(self.head + self.count) % self.size] = x
        if self.count < self.size:
            self.count += 1
        else:
            self.head = (self.head + 1) % self.size    # overwrite the oldest

    def items(self):
        return [self.buf[(self.head + i) % self.size] for i in range(self.count)]

r = Ring(3)
for x in range(1, 6):
    r.push(x)
print(r.items())     # [3, 4, 5]

import queue, threading

q = queue.Queue(maxsize=3)         # bounded buffer

def producer():
    for i in range(5):
        q.put(i)                   # blocks when full
    q.put(None)                    # signal: done

def consumer():
    while (item := q.get()) is not None:
        print("got", item)

t1, t2 = threading.Thread(target=producer), threading.Thread(target=consumer)
t1.start(); t2.start(); t1.join(); t2.join()
